 */

/* --- Accento --------------------------------------------------------- */
@define-color accent_bg_color        #5E81AC;  /* nord10 */
@define-color accent_fg_color        #ECEFF4;  /* nord6  */
@define-color accent_color           #88C0D0;  /* nord8 - testo/icone accentate */

