@define-color headerbar_bg_color        #3B4252;  /* nord1 */
@define-color headerbar_fg_color        #ECEFF4;  /* nord6 */
@define-color headerbar_border_color    #2E3440;
@define-color headerbar_backdrop_color  #2E3440;
@define-color headerbar_shade_color     rgba(0, 0, 0, 0.36);
@define-color headerbar_darker_shade_color rgba(0, 0, 0, 0.5);

/* --- Sidebar (libadwaita >= 1.4) -------------------------------------- */
@define-color sidebar_bg_color        #323844;
@define-color sidebar_fg_color        #D8DEE9;
@define-color sidebar_backdrop_color  #2E3440;
@define-color sidebar_border_color    rgba(0, 0, 0, 0.36);
@define-color sidebar_shade_color     rgba(0, 0, 0, 0.36);

@define-color secondary_sidebar_bg_color       #343B47;
@define-color secondary_sidebar_fg_color       #D8DEE9;
@define-color secondary_sidebar_backdrop_color #2E3440;
@define-color secondary_sidebar_border_color   rgba(0, 0, 0, 0.36);
@define-color secondary_sidebar_shade_color    rgba(0, 0, 0, 0.36);

/* --- Card, dialoghi, popover ------------------------------------------ */
@define-color card_bg_color      #3B4252;  /* nord1 */
@define-color card_fg_color      #D8DEE9;
@define-color card_shade_color   rgba(0, 0, 0, 0.36);

@define-color dialog_bg_color    #3B4252;
@define-color dialog_fg_color    #D8DEE9;

@define-color popover_bg_color   #3B4252;
@define-color popover_fg_color   #D8DEE9;
@define-color popover_shade_color rgba(0, 0, 0, 0.36);

/* --- Misc ------------------------------------------------------------- */
@define-color thumbnail_bg_color     #3B4252;
@define-color thumbnail_fg_color     #D8DEE9;
@define-color shade_color            rgba(0, 0, 0, 0.36);
@define-color scrollbar_outline_color rgba(0, 0, 0, 0.5);

