/* Nord per app GTK3 — copertura PARZIALE, vedi nota nel messaggio.
 * In GTK3 i colori del tema vengono risolti quando il tema viene caricato,
 * quindi ridefinirli qui non li ripropaga ovunque: servono selettori espliciti.
 */

@define-color theme_bg_color        #2E3440;
@define-color theme_base_color      #292E39;
@define-color theme_fg_color        #D8DEE9;
@define-color theme_text_color      #D8DEE9;
@define-color theme_selected_bg_color #5E81AC;
@define-color theme_selected_fg_color #ECEFF4;
@define-color insensitive_bg_color  #343B47;
@define-color insensitive_fg_color  #6B7385;
@define-color borders               #3B4252;

window,
dialog,
.background {
  background-color: #2E3440;
  color: #D8DEE9;
}

headerbar,
.titlebar,
toolbar {
  background-color: #3B4252;
  color: #ECEFF4;
  border-color: #2E3440;
}

textview text,
treeview.view,
entry,
list,
scrolledwindow viewport {
  background-color: #292E39;
  color: #D8DEE9;
}

menu, .menu, popover, popover.background, .popup {
  background-color: #3B4252;
  color: #D8DEE9;
}

*:selected,
*:selected:focus {
  background-color: #5E81AC;
  color: #ECEFF4;
}

button {
  background-image: none;
  background-color: #434C5E;
  color: #D8DEE9;
  border-color: #4C566A;
}

button:hover  { background-color: #4C566A; }
button:active,
button:checked { background-color: #5E81AC; color: #ECEFF4; }

